CREATE TABLE members (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, role VARCHAR(10) NOT NULL CHECK(role IN ('READER','WRITER')));
CREATE TABLE posts (id VARCHAR(36) PRIMARY KEY, author_id VARCHAR(36) NOT NULL REFERENCES members(id), title VARCHAR(180) NOT NULL, summary VARCHAR(400) NOT NULL, body TEXT NOT NULL, category VARCHAR(10) NOT NULL CHECK(category IN ('BLOG','FILM','SERIES')), work_title VARCHAR(160) NOT NULL, rating INTEGER CHECK(rating BETWEEN 1 AND 10), spoiler BOOLEAN NOT NULL, published BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE INDEX posts_feed ON posts(published,created_at);
CREATE TABLE comments (id VARCHAR(36) PRIMARY KEY, post_id VARCHAR(36) NOT NULL REFERENCES posts(id) ON DELETE CASCADE, member_id VARCHAR(36) NOT NULL REFERENCES members(id), body VARCHAR(2000) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE bookmarks (member_id VARCHAR(36) NOT NULL REFERENCES members(id), post_id VARCHAR(36) NOT NULL REFERENCES posts(id) ON DELETE CASCADE, PRIMARY KEY(member_id,post_id));
